begin;
alter table public.user_progress add column if not exists school_learning jsonb not null default '{}'::jsonb check(jsonb_typeof(school_learning)='object');
create table if not exists public.school_assessment_keys(slug text primary key,grade integer not null check(grade between 7 and 11),modes jsonb not null);
create table if not exists public.school_attempt_receipts(user_id uuid not null references auth.users(id) on delete cascade,item_id uuid not null references public.content_items(id) on delete cascade,attempt_id uuid not null,slug text not null,mode text not null,answers jsonb not null,created_at timestamptz not null default now(),primary key(user_id,item_id,attempt_id));
alter table public.school_assessment_keys enable row level security;
alter table public.school_attempt_receipts enable row level security;
revoke all on public.school_assessment_keys,public.school_attempt_receipts from public,anon,authenticated;
create or replace function public.guard_school_assessment() returns trigger language plpgsql set search_path='' as $$
begin
 if current_user in ('authenticated','anon') then
  if TG_OP='INSERT' then
   if new.school_learning <> '{}'::jsonb then raise exception 'use_school_rpc'; end if;
  elsif new.school_learning is distinct from old.school_learning then raise exception 'use_school_rpc'; end if;
 end if;
 return new;
end; $$;
drop trigger if exists guard_school_assessment on public.user_progress;
create trigger guard_school_assessment before insert or update on public.user_progress for each row execute function public.guard_school_assessment();

-- BEGIN GENERATED SCHOOL KEYS
-- END GENERATED SCHOOL KEYS
create or replace function public.submit_school_activity(p_item_id uuid,p_slug text,p_mode text,p_attempt_id uuid,p_answers jsonb)
returns setof public.user_progress language plpgsql security definer set search_path='' as $$
declare spec jsonb; g integer; prev jsonb; all_lessons jsonb; lesson jsonb; result jsonb; calculated integer:=0; maximum integer:=0; feedback jsonb:='[]'; pending boolean:=false; i integer; q jsonb; a jsonb; correct boolean; receipt public.school_attempt_receipts;
begin
 if auth.uid() is null or public.is_admin() then raise exception 'forbidden'; end if;
 select grade,modes->p_mode into g,spec from public.school_assessment_keys where slug=p_slug;
 if spec is null or p_attempt_id is null or p_answers is null or jsonb_typeof(p_answers)<>'array' or jsonb_array_length(p_answers)<>jsonb_array_length(spec) then raise exception 'invalid_activity'; end if;
 if not exists(select 1 from public.content_items where id=p_item_id and path='/mektep/teoriya/'||g||'-synyp' and is_published and public.content_is_visible(id)) then raise exception 'forbidden'; end if;
 if jsonb_array_length(spec)>0 then
 for i in 0..jsonb_array_length(spec)-1 loop
  q:=spec->i; a:=p_answers->i;
  if q->>'open'='true' then
   if jsonb_typeof(a)<>'string' or length(btrim(p_answers->>i))<15 or length(p_answers->>i)>3000 then raise exception 'invalid_text'; end if;
   pending:=true; feedback:=feedback||'[null]'::jsonb;
  else
   if jsonb_typeof(a)<>'number' or abs((p_answers->>i)::numeric)>1000000000 then raise exception 'invalid_number'; end if;
   if q ? 'choices' and ((p_answers->>i)::numeric<>trunc((p_answers->>i)::numeric) or (p_answers->>i)::numeric<0 or (p_answers->>i)::numeric >= (q->>'choices')::integer) then raise exception 'invalid_choice'; end if;
   correct:=abs((p_answers->>i)::numeric-(q->>'key')::numeric)<=0.0001;
   if correct then calculated:=calculated+1; end if;
   maximum:=maximum+1; feedback:=feedback||jsonb_build_array(correct);
  end if;
 end loop;
 end if;
 select school_learning into all_lessons from public.user_progress where user_id=auth.uid() and item_id=p_item_id for update;
 select * into receipt from public.school_attempt_receipts where user_id=auth.uid() and item_id=p_item_id and attempt_id=p_attempt_id;
 if found then
  if receipt.slug<>p_slug or receipt.mode<>p_mode or receipt.answers<>p_answers then raise exception 'attempt_conflict'; end if;
 else
  lesson:=coalesce(all_lessons->p_slug,'{}'); prev:=coalesce(lesson->p_mode,'{}');
  result:=jsonb_build_object('version',1,'completed',true,'attempt_id',p_attempt_id,'answers',p_answers,'score',calculated,'max_score',maximum,'feedback',feedback,'review_pending',pending,'best_score',greatest(calculated,coalesce((prev->>'best_score')::integer,0)),'attempt_count',coalesce((prev->>'attempt_count')::integer,0)+1,'tested_at',now());
  update public.user_progress set school_learning=jsonb_set(all_lessons,array[p_slug],jsonb_set(lesson,array[p_mode],result)),updated_at=now() where user_id=auth.uid() and item_id=p_item_id;
 end if;
 return query select * from public.user_progress where user_id=auth.uid() and item_id=p_item_id;
end; $$;
create or replace function public.review_school_activity(p_user_id uuid,p_item_id uuid,p_slug text,p_mode text,p_attempt_id uuid,p_score integer,p_comment text)
returns setof public.user_progress language plpgsql security definer set search_path='' as $$
declare data jsonb; activity jsonb; spec jsonb;
begin
 if auth.uid() is null or not public.is_admin() then raise exception 'forbidden'; end if;
 if p_score is null or p_score<0 or p_score>3 or p_comment is null or length(btrim(p_comment))<5 or length(p_comment)>1500 then raise exception 'invalid_review'; end if;
 select modes->p_mode into spec from public.school_assessment_keys where slug=p_slug;
 if spec is null or not exists(select 1 from jsonb_array_elements(spec) q where q->>'open'='true') then raise exception 'invalid_activity'; end if;
 select school_learning into data from public.user_progress where user_id=p_user_id and item_id=p_item_id for update;
 activity:=data->p_slug->p_mode;
 if activity is null or p_attempt_id is null or activity->>'attempt_id'<>p_attempt_id::text then raise exception 'stale_attempt'; end if;
 activity:=activity||jsonb_build_object('review_pending',false,'review',jsonb_build_object('score',p_score,'comment',btrim(p_comment),'reviewed_at',now(),'reviewer',auth.uid()));
 update public.user_progress set school_learning=jsonb_set(data,array[p_slug,p_mode],activity),updated_at=now() where user_id=p_user_id and item_id=p_item_id;
 return query select * from public.user_progress where user_id=p_user_id and item_id=p_item_id;
end; $$;
revoke all on function public.submit_school_activity(uuid,text,text,uuid,jsonb),public.review_school_activity(uuid,uuid,text,text,uuid,integer,text) from public,anon;
grant execute on function public.submit_school_activity(uuid,text,text,uuid,jsonb),public.review_school_activity(uuid,uuid,text,text,uuid,integer,text) to authenticated;
commit;
